"""PCA from scratch via SVD of the centered data matrix (numpy only)."""

import numpy as np


class PCA:
    def __init__(self, n_components=None):
        self.n_components = n_components

    def fit(self, X):
        X = np.asarray(X, dtype=float)
        n_samples, n_features = X.shape
        if self.n_components is None:
            k = min(n_samples, n_features)
        else:
            k = self.n_components
            if not 0 < k <= min(n_samples, n_features):
                raise ValueError(
                    "n_components must be in (0, min(n_samples, n_features)]"
                )

        # Center the data
        self.mean_ = X.mean(axis=0)
        Xc = X - self.mean_

        # SVD of centered data: Xc = U S Vt
        U, S, Vt = np.linalg.svd(Xc, full_matrices=False)

        total_var = (S**2).sum() / max(n_samples - 1, 1)
        self.explained_variance_ = (S[:k] ** 2) / max(n_samples - 1, 1)
        if total_var > 0:
            self.explained_variance_ratio_ = self.explained_variance_ / total_var
        else:
            self.explained_variance_ratio_ = np.zeros(k)

        self.components_ = Vt[:k]          # (k, n_features)
        self.singular_values_ = S[:k]
        return self

    def transform(self, X):
        X = np.asarray(X, dtype=float)
        return (X - self.mean_) @ self.components_.T

    def fit_transform(self, X):
        return self.fit(X).transform(X)

    def inverse_transform(self, Z):
        Z = np.asarray(Z, dtype=float)
        return Z @ self.components_ + self.mean_

